Object.assign(SNIP,{"l40pair": "pair<string, int> p(\"An\", 20);        // hai giá trị đi cùng nhau\ncout << p.first << \" \" << p.second;  // first, second\nauto q = make_pair(3, 'x');          // make_pair tự suy kiểu: pair<int, char>\npair<int, int> r = {2, 5};           // hoặc liệt kê trong { }\n// so sánh theo first trước, bằng nhau mới xét second: (1, 9) < (2, 0)", "l40map": "map<string, int> dem;\ndem[\"an\"]++;                         // chưa có \"an\": tự tạo với giá trị 0 rồi tăng\ndem.count(\"binh\");                   // 0 hoặc 1: kiểm tra có khóa không, KHÔNG tạo khóa\nauto it = dem.find(\"an\");            // it->first, it->second; không có thì it == dem.end()\nfor (auto& [k, v] : dem)             // duyệt theo khóa tăng dần\n    cout << k << \": \" << v << \"\\n\";"});PRESET_NOTES["l40"]={"Ví dụ: stack đảo ngược một dãy": "push đặt lên đỉnh, pop lấy từ đỉnh: vào sau ra trước nên dãy in ra bị đảo ngược. pop() không trả về giá trị, nên phải đọc top() trước.", "Ví dụ: queue phục vụ theo lượt": "Vào ở cuối (push), ra ở đầu (front rồi pop): ai đến trước được phục vụ trước. Dung đến sau cùng nên ra cuối cùng.", "Ví dụ: priority_queue luôn lấy lớn nhất": "Bên trong là cây đống nhị phân nằm trong một mảng: cha luôn lớn hơn hai con nên đỉnh là lớn nhất, nhưng các phần tử khác KHÔNG sắp hẳn. Mỗi lần pop, phần tử cuối được đưa lên đỉnh rồi “chìm” xuống đúng chỗ. greater<int> đảo chiều: đỉnh là nhỏ nhất.", "Ví dụ: set loại trùng và sắp xếp": "Chèn 3 và 5 lần thứ hai không có tác dụng: set không chứa giá trị trùng. Duyệt set luôn ra thứ tự tăng dần. count(x) chỉ là 0 hoặc 1; lower_bound(6) tìm phần tử nhỏ nhất không nhỏ hơn 6.", "Ví dụ: map đếm số lần xuất hiện": "dem[x]++ với khóa chưa có: map tự tạo khóa với giá trị 0 rồi tăng lên 1. Duyệt map ra theo khóa tăng dần (cho, ga, meo), không theo thứ tự thêm. auto& [k, v] tách mỗi phần tử (một pair) thành khóa và giá trị.", "Bẫy: m[k] tự thêm khóa": "Chỉ đọc diem[\"Binh\"] để kiểm tra mà map đã có thêm khóa \"Binh\" với điểm 0: size tăng từ 1 lên 2. count(\"Chi\") chỉ hỏi, không thêm gì nên size vẫn là 2.", "Ví dụ: unordered_map và các bucket": "Thứ tự duyệt không theo bảng chữ cái cũng không theo thứ tự thêm: nó theo các bucket mà hàm băm chọn. Hình động cho thấy mỗi khóa nằm ở bucket nào trong 13 bucket. Kết quả giống hệt khi chạy bằng g++.", "Ví dụ: pair và vector của pair": "sort xếp pair theo first trước; first bằng nhau (8, 8) thì xét second (An trước Chi). (1, 9) < (2, 0) vì first 1 < 2, không cần xét second.", "Ví dụ: deque thêm ở hai đầu": "deque (hàng đợi hai đầu) thêm, bớt ở đầu nhanh như ở cuối, và vẫn truy cập d[i] như vector. vector cũng thêm được ở đầu (insert) nhưng phải dời mọi phần tử.", "Lỗi: queue không có top": "top() là của stack và priority_queue. Đầu hàng đợi lấy bằng front(). g++ còn gợi ý: did you mean 'pop'? vì pop viết gần giống top."};EX_HINTS["l40"]=[["dem[s]++ tự tạo khóa mới với giá trị 0.", "map đã duyệt theo bảng chữ cái, nên chỉ đổi kết quả khi v > maxDem (lớn hơn hẳn) là được từ đứng trước khi bằng nhau."], ["pair so sánh first trước: mức nặng lớn hơn lên đỉnh trước.", "Cùng mức thì second lớn hơn lên trước; dùng −thứ_tự để người đến trước (thứ tự nhỏ) có second lớn hơn."], ["Khi đọc tới a, mọi phần tử trước đó ghép được với a là các phần tử bằng x − a: số lượng của chúng nằm trong daGap[x − a].", "Dùng find (không dùng daGap[x − a]) để không thêm khóa thừa; sau đó mới tăng daGap[a]."]];
/* ===================== BÀI 40 · Container của STL ===================== */
/* Bài 40 · Container của STL
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P40=[{label:"Ví dụ: stack đảo ngược một dãy",input:"",code:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    stack<string> s;\n    string tu[] = {\"mot\", \"hai\", \"ba\", \"bon\"};\n    for (string x : tu) {\n        s.push(x);\n    }\n    cout << \"Dinh: \" << s.top() << \", co \" << s.size() << \" phan tu\\n\";\n    while (!s.empty()) {\n        cout << s.top() << \" \";\n        s.pop();\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"s"}]},{label:"Ví dụ: queue phục vụ theo lượt",input:"",code:"#include <iostream>\n#include <queue>\n#include <string>\nusing namespace std;\n\nint main() {\n    queue<string> q;\n    q.push(\"An\");\n    q.push(\"Binh\");\n    q.push(\"Chi\");\n    cout << \"Dau: \" << q.front() << \", cuoi: \" << q.back() << \"\\n\";\n    q.pop();\n    q.push(\"Dung\");\n    while (!q.empty()) {\n        cout << \"Phuc vu \" << q.front() << \"\\n\";\n        q.pop();\n    }\n    return 0;\n}",viz:[{type:"cont",of:"q"}]},{label:"Ví dụ: priority_queue luôn lấy lớn nhất",input:"",code:"#include <iostream>\n#include <queue>\nusing namespace std;\n\nint main() {\n    priority_queue<int> lon;\n    priority_queue<int, vector<int>, greater<int>> nho;\n    int a[] = {5, 1, 8, 3, 9, 2, 7};\n    for (int x : a) {\n        lon.push(x);\n        nho.push(x);\n    }\n    cout << \"Lon nhat: \" << lon.top() << \", nho nhat: \" << nho.top() << \"\\n\";\n    while (!lon.empty()) {\n        cout << lon.top() << \" \";\n        lon.pop();\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"lon"},{type:"cont",of:"nho"}]},{label:"Ví dụ: set loại trùng và sắp xếp",input:"",code:"#include <iostream>\n#include <set>\nusing namespace std;\n\nint main() {\n    set<int> s;\n    int a[] = {5, 3, 8, 3, 1, 5, 9};\n    for (int x : a) {\n        s.insert(x);\n    }\n    cout << \"Co \" << s.size() << \" gia tri khac nhau: \";\n    for (int x : s) {\n        cout << x << \" \";\n    }\n    cout << \"\\n\";\n    cout << s.count(8) << \" \" << s.count(4) << \"\\n\";\n    s.erase(3);\n    auto it = s.lower_bound(6);\n    cout << \"Nho nhat >= 6: \" << *it << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"s"}]},{label:"Ví dụ: map đếm số lần xuất hiện",input:"",code:"#include <iostream>\n#include <map>\n#include <string>\nusing namespace std;\n\nint main() {\n    string van[] = {\"meo\", \"cho\", \"meo\", \"ga\", \"cho\", \"meo\"};\n    map<string, int> dem;\n    for (string x : van) {\n        dem[x]++;\n    }\n    for (auto& [k, v] : dem) {\n        cout << k << \": \" << v << \"\\n\";\n    }\n    auto it = dem.find(\"ga\");\n    if (it != dem.end()) {\n        cout << \"Tim thay \" << it->first << \" = \" << it->second << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cont",of:"dem"}]},{label:"Bẫy: m[k] tự thêm khóa",input:"",code:"#include <iostream>\n#include <map>\n#include <string>\nusing namespace std;\n\nint main() {\n    map<string, int> diem;\n    diem[\"An\"] = 8;\n    cout << \"So hoc vien: \" << diem.size() << \"\\n\";\n    if (diem[\"Binh\"] == 0) {\n        cout << \"Binh chua co diem\\n\";\n    }\n    cout << \"So hoc vien: \" << diem.size() << \"\\n\";\n    if (diem.count(\"Chi\") == 0) {\n        cout << \"Chi chua co diem\\n\";\n    }\n    cout << \"So hoc vien: \" << diem.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"diem"}]},{label:"Ví dụ: unordered_map và các bucket",input:"",code:"#include <iostream>\n#include <unordered_map>\n#include <string>\nusing namespace std;\n\nint main() {\n    unordered_map<string, int> gia;\n    gia[\"tao\"] = 12;\n    gia[\"cam\"] = 20;\n    gia[\"le\"] = 15;\n    gia[\"chuoi\"] = 8;\n    cout << \"So bucket: \" << gia.bucket_count() << \"\\n\";\n    for (auto& [k, v] : gia) {\n        cout << k << \" \" << v << \"\\n\";\n    }\n    cout << gia.count(\"cam\") << \" \" << gia.at(\"le\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"gia"}]},{label:"Ví dụ: pair và vector của pair",input:"",code:"#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<pair<int, string>> ds;\n    ds.push_back(make_pair(8, \"An\"));\n    ds.push_back({9, \"Binh\"});\n    ds.push_back({8, \"Chi\"});\n    sort(ds.begin(), ds.end());\n    for (auto& [diem, ten] : ds) {\n        cout << diem << \" \" << ten << \"\\n\";\n    }\n    pair<int, int> a = {1, 9}, b = {2, 0};\n    cout << (a < b) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: deque thêm ở hai đầu",input:"",code:"#include <iostream>\n#include <deque>\nusing namespace std;\n\nint main() {\n    deque<int> d;\n    d.push_back(2);\n    d.push_back(3);\n    d.push_front(1);\n    d.push_front(0);\n    for (int x : d) {\n        cout << x << \" \";\n    }\n    cout << \"\\n\" << d[1] << \" \" << d.front() << \" \" << d.back() << \"\\n\";\n    d.pop_front();\n    d.pop_back();\n    cout << d.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"d"}]},{label:"Lỗi: queue không có top",input:"",code:"#include <iostream>\n#include <queue>\nusing namespace std;\n\nint main() {\n    queue<int> q;\n    q.push(1);\n    q.push(2);\n    cout << q.top() << \"\\n\";\n    return 0;\n}"}];
const sim40=makeSim2(document.getElementById("sim-l40"),{id:"s40",presets:P40});
makeEx2(document.getElementById("ex-l40"),sim40,[{t:"Đếm từ",d:"Nhập n rồi n từ (chữ thường, không dấu cách). In mỗi từ khác nhau kèm số lần xuất hiện, theo thứ tự bảng chữ cái, dạng <code>tu so_lan<\/code>. Dòng cuối in <code>Nhieu nhat: tu<\/code> (bằng nhau thì lấy từ đứng trước theo bảng chữ cái).",tests:[{in:"6\nmeo cho meo ga cho meo",out:"cho 2\nga 1\nmeo 3\nNhieu nhat: meo"},{in:"1\nx",out:"x 1\nNhieu nhat: x"},{in:"4\nb a b a",out:"a 2\nb 2\nNhieu nhat: a"}],start:"#include <iostream>\n#include <map>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // map<string, int> dem;\n    for (int i = 0; i < n; i++) {\n        string s;\n        cin >> s;\n    }\n    return 0;\n}",need:/map\s*<\s*string\s*,\s*int\s*>/,needMsg:"Hãy dùng map<string, int> để đếm."},{t:"Phòng khám ưu tiên",d:"Bệnh nhân có mức nặng từ 1 đến 9. Lệnh <code>den ten muc<\/code>: bệnh nhân vào hàng chờ; lệnh <code>kham<\/code>: khám người có mức nặng lớn nhất, bằng nhau thì người đến trước, in <code>Kham ten<\/code> (hàng chờ rỗng thì in <code>Khong co ai<\/code>). Dùng <code>priority_queue&lt;pair&lt;int, int&gt;&gt;<\/code> với pair (mức nặng, −thứ tự đến) và một vector lưu tên. Nhập q rồi q lệnh. Cuối cùng in <code>Con cho: k<\/code>.",tests:[{in:"6\nden An 3\nden Binh 7\nden Chi 7\nkham\nkham\nkham",out:"Kham Binh\nKham Chi\nKham An\nCon cho: 0"},{in:"3\nkham\nden Tu 1\nden Ha 1",out:"Khong co ai\nCon cho: 2"},{in:"4\nden A 5\nkham\nden B 2\nkham",out:"Kham A\nKham B\nCon cho: 0"}],start:"#include <iostream>\n#include <queue>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int q;\n    cin >> q;\n    priority_queue<pair<int, int>> pq;\n    vector<string> ten;\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // den: đọc tên, mức; ten.push_back(...); pq.push({muc, -thứ_tự})\n        // kham: lấy pq.top(), in tên, pop\n    }\n    cout << \"Con cho: \" << pq.size() << \"\\n\";\n    return 0;\n}",need:/priority_queue\s*<\s*pair\s*</,needMsg:"Hãy dùng priority_queue<pair<int, int>>."},{t:"Cặp có tổng bằng x",d:"Nhập n, x rồi n số nguyên (|a[i]| ≤ 10⁹). Đếm số cặp chỉ số i &lt; j có a[i] + a[j] = x. Bài này được chấm cả độ hiệu quả: duyệt mọi cặp (O(n²)) sẽ quá chậm với n lớn. Gợi ý: đi qua dãy một lần, dùng <code>unordered_map<\/code> (hoặc map) nhớ mỗi giá trị đã gặp bao nhiêu lần.",tests:[{in:"5 6\n1 5 3 3 7",out:"2"},{in:"4 0\n0 0 0 0",out:"6"},{in:"3 10\n1 2 3",out:"0"},{in:"6 2000000000\n1000000000 1000000000 1000000000 -5 5 1999999995",out:"4"}],start:"#include <iostream>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int n;\n    long long x;\n    cin >> n >> x;\n    long long dem = 0;\n    // unordered_map<long long, long long> daGap;\n    for (int i = 0; i < n; i++) {\n        long long a;\n        cin >> a;\n        // cộng số lần đã gặp (x - a) vào dem, rồi ghi nhận a\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",need:/(unordered_)?map\s*</,needMsg:"Hãy dùng unordered_map (hoặc map) để nhớ các giá trị đã gặp.",perf:{gen:n=>n+" 100\n"+Array.from({length:n},(_,i)=>(i*37)%101).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+500,why:"Duyệt mọi cặp là O(n²). Mỗi lần tra unordered_map chỉ tốn trung bình O(1), nên cả bài O(n)."}}]);

makeQuiz("quiz40","score40",[{"q": "Cần lấy ra phần tử theo thứ tự <b>ngược<\/b> với lúc thêm vào. Chọn container nào?", "o": ["queue", "stack", "set", "priority_queue"], "a": 1, "e": "stack: vào sau ra trước."}, {"q": "<code>map&lt;string, int&gt; m;<\/code> rỗng. Sau <code>if (m[\"a\"] == 0) {}<\/code>, <code>m.size()<\/code> là bao nhiêu?", "o": ["0", "1", "Lỗi biên dịch", "Lỗi khi chạy"], "a": 1, "e": "m[k] thêm khóa k (giá trị 0) nếu chưa có. Muốn chỉ kiểm tra thì dùng count hoặc find."}, {"q": "Chèn 5, 1, 5, 3 vào một <code>set&lt;int&gt;<\/code> rồi duyệt. Kết quả là:", "o": ["5 1 5 3", "1 3 5 5", "1 3 5", "5 1 3"], "a": 2, "e": "set không chứa giá trị trùng và luôn tăng dần."}, {"q": "Vì sao <code>unordered_map<\/code> thường nhanh hơn <code>map<\/code> khi tra cứu?", "o": ["Vì nó sắp xếp sẵn", "Vì dùng bảng băm: tính hash rồi xem đúng một bucket, trung bình O(1)", "Vì nó tốn ít bộ nhớ hơn", "Vì nó dùng tìm kiếm nhị phân"], "a": 1, "e": "map là cây cân bằng (O(log n)); unordered_map là bảng băm (trung bình O(1)) nhưng không giữ thứ tự."}]);

